#!/usr/bin/env bash
# Partie « Stockage et médias » : carte des entités et parcours (envoyer et servir un fichier, le Finder).
# Prérequis : apply-carte-contenu.sh.
# Usage (racine du repo) : bash apply-carte-stockage.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/stockage/envoyer-et-servir-un-fichier.mdx" 2>/dev/null | grep -qF "Envoyer une photo dans la bibliothèque"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Un visiteur lit la page" "apps/web/content/docs/dev/contenu/constructeur-de-pages.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-carte-contenu.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/stockage/envoyer-et-servir-un-fichier.mdx" "apps/web/content/docs/dev/stockage/le-finder.mdx" "scripts/build-procedure-map.mjs" "apps/web/src/features/docs/entities/procedureMap.generated.json")
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Envoyer une photo dans la bibliothèque" "apps/web/content/docs/dev/stockage/envoyer-et-servir-un-fichier.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/docs/entities"
base64 -d > "apps/web/src/features/docs/entities/procedureMap.generated.json" <<'B64'
